=== FILE: tb/tb_irq_ctrl.sv ===
`timescale 1ns / 1ps
// Self-checking testbench for irq_ctrl (interface_spec.md).
// Expected values come from (a) constants worked out by hand from the
// specification and (b) the reference model irq_ref below, written from the
// specification's behaviour statements. Nothing expected is read from the DUT.
// Inputs are driven at the falling edge of clk; outputs are checked 1 ns later.

// ---------------------------------------------------------------------------
// Reference model, from interface_spec.md section 4.
// ---------------------------------------------------------------------------
module irq_ref #(
    parameter integer N = 8
) (
    input  logic         clk,
    input  logic         rst_n,
    input  logic [N-1:0] src,
    input  logic         we,
    input  logic [1:0]   addr,
    input  logic [31:0]  wdata,
    output logic [31:0]  exp_rdata,
    output logic         exp_irq,
    output logic [4:0]   exp_id
);
    logic [N-1:0] en_r, md_r, pend_r, lvl_r;
    logic [N-1:0] pend_n;
    logic         det, clr, found;
    integer       k, j;

    // IRQ-RESET, IRQ-REG-RW, IRQ-LEVEL, IRQ-EDGE, IRQ-DETECT-DISABLED,
    // IRQ-W1C, IRQ-ACK, IRQ-SET-WINS, stated per source.
    always @(posedge clk) begin
        if (!rst_n) begin
            en_r   <= '0;
            md_r   <= '0;
            pend_r <= '0;
            lvl_r  <= '0;
        end else begin
            pend_n = pend_r;
            for (k = 0; k < N; k = k + 1) begin
                if (md_r[k])
                    det = src[k] && !lvl_r[k];   // rising edge
                else
                    det = src[k];                // high level
                clr = (we && addr == 2'd2 && wdata[k]) ||
                      (we && addr == 2'd3 && wdata[4:0] == k);
                if (det)
                    pend_n[k] = 1'b1;            // detection wins over a clear
                else if (clr)
                    pend_n[k] = 1'b0;
            end
            pend_r <= pend_n;
            if (we && addr == 2'd0) en_r <= wdata[N-1:0];
            if (we && addr == 2'd1) md_r <= wdata[N-1:0];
            lvl_r <= src;
        end
    end

    // IRQ-MASK, IRQ-PRIORITY, IRQ-CLAIM, IRQ-READ, IRQ-PARAM.
    always @* begin
        found  = 1'b0;
        exp_id = 5'd0;
        for (j = 0; j < N; j = j + 1)
            if (!found && pend_r[j] && en_r[j]) begin
                found  = 1'b1;
                exp_id = j[4:0];
            end
        exp_irq   = found;
        exp_rdata = 32'd0;
        case (addr)
            2'd0: for (j = 0; j < N; j = j + 1) exp_rdata[j] = en_r[j];
            2'd1: for (j = 0; j < N; j = j + 1) exp_rdata[j] = md_r[j];
            2'd2: for (j = 0; j < N; j = j + 1) exp_rdata[j] = pend_r[j];
            default: exp_rdata = {found, 26'd0, exp_id};
        endcase
    end
endmodule

// ---------------------------------------------------------------------------
// Top-level testbench.
// ---------------------------------------------------------------------------
module tb_irq_ctrl;
    logic        clk = 1'b0;
    logic        rst_n;
    logic        we;
    logic [1:0]  addr;
    logic [31:0] wdata;
    logic [31:0] src_w;

    wire  [31:0] rdata8, rdata32, rdata2;
    wire         irq8, irq32, irq2;
    wire  [4:0]  id8, id32, id2;
    wire  [31:0] e_rdata8, e_rdata32, e_rdata2;
    wire         e_irq8, e_irq32, e_irq2;
    wire  [4:0]  e_id8, e_id32, e_id2;

    int          pass_cnt = 0;
    int          fail_cnt = 0;
    string       phase;
    string       nonce;

    integer      seed;
    integer      n;
    logic [31:0] r1, r2, r3, wd, src_v;

    always #5 clk = ~clk;

    irq_ctrl #(.N(8)) dut8 (
        .clk(clk), .rst_n(rst_n), .src(src_w[7:0]), .we(we), .addr(addr),
        .wdata(wdata), .rdata(rdata8), .irq(irq8), .irq_id(id8));
    irq_ref #(.N(8)) ref8 (
        .clk(clk), .rst_n(rst_n), .src(src_w[7:0]), .we(we), .addr(addr),
        .wdata(wdata), .exp_rdata(e_rdata8), .exp_irq(e_irq8), .exp_id(e_id8));

    irq_ctrl #(.N(32)) dut32 (
        .clk(clk), .rst_n(rst_n), .src(src_w), .we(we), .addr(addr),
        .wdata(wdata), .rdata(rdata32), .irq(irq32), .irq_id(id32));
    irq_ref #(.N(32)) ref32 (
        .clk(clk), .rst_n(rst_n), .src(src_w), .we(we), .addr(addr),
        .wdata(wdata), .exp_rdata(e_rdata32), .exp_irq(e_irq32), .exp_id(e_id32));

    irq_ctrl #(.N(2)) dut2 (
        .clk(clk), .rst_n(rst_n), .src(src_w[1:0]), .we(we), .addr(addr),
        .wdata(wdata), .rdata(rdata2), .irq(irq2), .irq_id(id2));
    irq_ref #(.N(2)) ref2 (
        .clk(clk), .rst_n(rst_n), .src(src_w[1:0]), .we(we), .addr(addr),
        .wdata(wdata), .exp_rdata(e_rdata2), .exp_irq(e_irq2), .exp_id(e_id2));

    // Every compare counts as a pass or a failure.
    task automatic check(input string what, input logic [31:0] got, input logic [31:0] exp);
        if (got === exp)
            pass_cnt = pass_cnt + 1;
        else begin
            fail_cnt = fail_cnt + 1;
            $display("FAIL [%s] %s: got %h, expected %h at %0t", phase, what, got, exp, $time);
        end
    endtask

    // All outputs of all instances against the reference model.
    task automatic check_all();
        check("N=8 rdata vs model",   rdata8,  e_rdata8);
        check("N=8 irq vs model",     irq8,    e_irq8);
        check("N=8 irq_id vs model",  id8,     e_id8);
        check("N=32 rdata vs model",  rdata32, e_rdata32);
        check("N=32 irq vs model",    irq32,   e_irq32);
        check("N=32 irq_id vs model", id32,    e_id32);
        check("N=2 rdata vs model",   rdata2,  e_rdata2);
        check("N=2 irq vs model",     irq2,    e_irq2);
        check("N=2 irq_id vs model",  id2,     e_id2);
    endtask

    // One clock cycle: drive at the falling edge, check 1 ns later.
    task automatic cyc(input logic w, input logic [1:0] a, input logic [31:0] d,
                       input logic [31:0] s);
        @(negedge clk);
        we    = w;
        addr  = a;
        wdata = d;
        src_w = s;
        #1;
        check_all();
    endtask

    task automatic wr(input logic [1:0] a, input logic [31:0] d);
        cyc(1'b1, a, d, src_w);
    endtask

    task automatic rd(input logic [1:0] a);
        cyc(1'b0, a, 32'd0, src_w);
    endtask

    task automatic rd8(input logic [1:0] a, input logic [31:0] exp, input string what);
        rd(a);
        check(what, rdata8, exp);
    endtask

    task automatic set_src(input logic [31:0] s);
        cyc(1'b0, addr, 32'd0, s);
    endtask

    task automatic set_rst(input logic v);
        @(negedge clk);
        rst_n = v;
        we    = 1'b0;
        #1;
        check_all();
    endtask

    initial begin
        nonce = "unset";
        if (!$value$plusargs("nonce=%s", nonce))
            if (!$value$plusargs("NIRMAAN_NONCE=%s", nonce))
                if (!$value$plusargs("nirmaan_nonce=%s", nonce))
                    if (!$value$plusargs("NIRMAAN_SIM_NONCE=%s", nonce))
                        $display("NOTE: no nonce plusarg found");

        rst_n = 1'b0;
        we    = 1'b0;
        addr  = 2'd0;
        wdata = 32'd0;
        src_w = 32'd0;
        src_v = 32'd0;

        // ---------------- IRQ-RESET ----------------
        phase = "reset";
        repeat (2) @(posedge clk);
        @(negedge clk);
        #1;
        check_all();
        rd8(2'd0, 32'h0, "ENABLE is 0 in reset");
        rd8(2'd1, 32'h0, "MODE is 0 in reset");
        rd8(2'd2, 32'h0, "PENDING is 0 in reset");
        rd8(2'd3, 32'h0, "CLAIM is 0 in reset");
        check("irq low in reset", irq8, 1'b0);
        check("irq_id 0 in reset", id8, 5'd0);
        set_rst(1'b1);

        // ---------------- IRQ-REG-RW, IRQ-PARAM ----------------
        phase = "reg_rw";
        wr(2'd0, 32'hFFFF_FFA5);
        rd(2'd0);
        check("N=8 ENABLE keeps bits 7:0 only", rdata8, 32'h0000_00A5);
        check("N=32 ENABLE keeps all bits", rdata32, 32'hFFFF_FFA5);
        check("N=2 ENABLE keeps bits 1:0 only", rdata2, 32'h0000_0001);
        rd8(2'd1, 32'h0, "MODE unchanged by ENABLE write");
        rd8(2'd2, 32'h0, "PENDING unchanged by ENABLE write");
        wr(2'd1, 32'hFFFF_FF5A);
        rd(2'd1);
        check("N=8 MODE keeps bits 7:0 only", rdata8, 32'h0000_005A);
        check("N=32 MODE keeps all bits", rdata32, 32'hFFFF_FF5A);
        check("N=2 MODE keeps bits 1:0 only", rdata2, 32'h0000_0002);
        rd8(2'd0, 32'h0000_00A5, "ENABLE unchanged by MODE write");
        wr(2'd2, 32'hFFFF_FFFF);
        rd8(2'd2, 32'h0, "PENDING write never sets a bit");
        wr(2'd3, 32'd0);
        rd8(2'd2, 32'h0, "ack with nothing pending changes nothing");
        wr(2'd1, 32'h0);
        wr(2'd0, 32'h0);
        rd8(2'd1, 32'h0, "MODE cleared by write");
        rd8(2'd0, 32'h0, "ENABLE cleared by write");

        // ---------------- IRQ-READ ----------------
        phase = "read";
        wr(2'd0, 32'h0F);
        wr(2'd1, 32'hF0);
        @(negedge clk);
        we = 1'b0;
        addr = 2'd0; #1; check_all(); check("rdata follows addr=0 without edge", rdata8, 32'h0F);
        addr = 2'd1; #1; check_all(); check("rdata follows addr=1 without edge", rdata8, 32'hF0);
        addr = 2'd2; #1; check_all(); check("rdata follows addr=2 without edge", rdata8, 32'h00);
        addr = 2'd3; #1; check_all(); check("rdata follows addr=3 without edge", rdata8, 32'h00);
        rd8(2'd0, 32'h0F, "ENABLE unchanged by reads");
        rd8(2'd1, 32'hF0, "MODE unchanged by reads");
        wr(2'd0, 32'h0);
        wr(2'd1, 32'h0);

        // ---------------- IRQ-LEVEL, IRQ-DETECT-DISABLED, IRQ-MASK, IRQ-LATENCY ----------------
        phase = "level";
        set_src(32'h08);
        set_src(32'h00);
        rd8(2'd2, 32'h08, "disabled level source sets PENDING");
        check("irq low while source disabled", irq8, 1'b0);
        check("irq_id 0 while irq low", id8, 5'd0);
        rd8(2'd3, 32'h0, "CLAIM reads 0 while irq low");
        rd8(2'd2, 32'h08, "PENDING holds after source drops");
        wr(2'd0, 32'h08);
        rd8(2'd3, 32'h8000_0003, "CLAIM after enabling source 3");
        check("irq high once pending and enabled", irq8, 1'b1);
        check("irq_id names source 3", id8, 5'd3);
        wr(2'd2, 32'h08);
        rd8(2'd2, 32'h0, "W1C clears PENDING bit 3");
        check("irq low after clear", irq8, 1'b0);
        cyc(1'b0, 2'd3, 32'd0, 32'h08);
        check("irq still low before the sampling edge", irq8, 1'b0);
        cyc(1'b0, 2'd3, 32'd0, 32'h00);
        check("CLAIM one edge after detection", rdata8, 32'h8000_0003);
        check("irq high one edge after detection", irq8, 1'b1);
        wr(2'd2, 32'h08);
        rd8(2'd2, 32'h0, "PENDING cleared again");

        // ---------------- IRQ-SET-WINS (level) ----------------
        phase = "level_hold";
        set_src(32'h04);
        rd8(2'd2, 32'h04, "held level source pending");
        check("irq low: source 2 disabled", irq8, 1'b0);
        wr(2'd2, 32'h04);
        rd8(2'd2, 32'h04, "W1C loses to held level source");
        wr(2'd3, 32'd2);
        rd8(2'd2, 32'h04, "ack loses to held level source");
        set_src(32'h00);
        wr(2'd3, 32'd2);
        rd8(2'd2, 32'h0, "ack clears once source low");

        // ---------------- IRQ-EDGE, IRQ-SET-WINS (edge) ----------------
        phase = "edge";
        wr(2'd1, 32'h20);
        wr(2'd0, 32'h20);
        set_src(32'h20);
        rd8(2'd2, 32'h20, "edge source sets on rising edge");
        rd8(2'd3, 32'h8000_0005, "CLAIM names edge source 5");
        wr(2'd2, 32'h20);
        rd8(2'd2, 32'h0, "edge source held high does not set again");
        rd8(2'd2, 32'h0, "edge source still clear while held");
        check("irq low after clearing edge source", irq8, 1'b0);
        set_src(32'h00);
        rd8(2'd2, 32'h0, "falling edge sets nothing");
        cyc(1'b1, 2'd2, 32'h20, 32'h20);
        rd8(2'd2, 32'h20, "edge detection wins over W1C at the same edge");
        wr(2'd3, 32'd5);
        rd8(2'd2, 32'h0, "ack clears held edge source");
        set_src(32'h00);
        wr(2'd1, 32'h0);
        wr(2'd0, 32'h0);

        // ---------------- IRQ-PRIORITY, IRQ-CLAIM ----------------
        phase = "priority";
        wr(2'd0, 32'hFF);
        set_src(32'h52);
        set_src(32'h00);
        rd8(2'd2, 32'h52, "sources 1, 4, 6 pending together");
        rd8(2'd3, 32'h8000_0001, "lowest-numbered source 1 wins");
        wr(2'd3, 32'd1);
        rd8(2'd2, 32'h50, "ack clears only source 1");
        rd8(2'd3, 32'h8000_0004, "source 4 next after ack");
        wr(2'd0, 32'hFE);
        set_src(32'h01);
        set_src(32'h00);
        rd8(2'd2, 32'h51, "disabled source 0 still pending");
        rd8(2'd3, 32'h8000_0004, "disabled source 0 does not win");
        wr(2'd0, 32'hFF);
        rd8(2'd3, 32'h8000_0000, "source 0 wins with irq high");
        check("irq high with source 0", irq8, 1'b1);
        check("irq_id 0 for source 0", id8, 5'd0);
        wr(2'd2, 32'hFF);
        rd8(2'd3, 32'h0, "CLAIM 0 after clearing all");
        set_src(32'h81);
        set_src(32'h00);
        rd8(2'd3, 32'h8000_0000, "source 0 beats source 7 in the same cycle");
        wr(2'd3, 32'd0);
        rd8(2'd3, 32'h8000_0007, "source 7 after ack of source 0");
        wr(2'd3, 32'd7);
        rd8(2'd3, 32'h0, "CLAIM 0 after all acknowledged");
        check("irq low after all acknowledged", irq8, 1'b0);

        // ---------------- IRQ-ACK, IRQ-W1C ----------------
        phase = "ack";
        set_src(32'h3C);
        set_src(32'h00);
        rd8(2'd2, 32'h3C, "sources 2 to 5 pending");
        wr(2'd3, 32'd8);
        rd8(2'd2, 32'h3C, "ack of source 8 (N or more) changes nothing");
        wr(2'd3, 32'd31);
        rd8(2'd2, 32'h3C, "ack of source 31 changes nothing at N=8");
        wr(2'd3, 32'hFFFF_FFE4);
        rd8(2'd2, 32'h2C, "ack uses wdata[4:0] only and clears source 4");
        wr(2'd2, 32'h24);
        rd8(2'd2, 32'h08, "W1C clears only bits written 1");
        wr(2'd2, 32'h00);
        rd8(2'd2, 32'h08, "W1C of zeros changes nothing");
        wr(2'd2, 32'hFFFF_FFFF);
        rd8(2'd2, 32'h0, "W1C of all ones clears all");

        // ---------------- IRQ-RESET in the middle of operation ----------------
        phase = "reset_mid";
        wr(2'd1, 32'hF0);
        set_src(32'h0F);
        rd8(2'd2, 32'h0F, "level sources 0-3 pending before reset");
        check("irq high before reset", irq8, 1'b1);
        set_rst(1'b0);
        rd8(2'd0, 32'h0, "ENABLE cleared by reset");
        rd8(2'd1, 32'h0, "MODE cleared by reset");
        rd8(2'd2, 32'h0, "PENDING cleared by reset with sources high");
        rd8(2'd3, 32'h0, "CLAIM 0 in reset");
        check("irq low in reset", irq8, 1'b0);
        set_rst(1'b1);
        rd8(2'd2, 32'h0F, "level sources detected again after reset");
        check("irq low: ENABLE 0 after reset", irq8, 1'b0);
        set_src(32'h00);
        wr(2'd2, 32'hFF);

        // ---------------- IRQ-PARAM on N=32 and N=2 ----------------
        phase = "param";
        wr(2'd0, 32'hFFFF_FFFF);
        rd(2'd0);
        check("N=8 ENABLE all ones", rdata8, 32'h0000_00FF);
        check("N=32 ENABLE all ones", rdata32, 32'hFFFF_FFFF);
        check("N=2 ENABLE all ones", rdata2, 32'h0000_0003);
        set_src(32'h8000_0000);
        set_src(32'h0);
        rd(2'd3);
        check("N=32 CLAIM names source 31", rdata32, 32'h8000_001F);
        check("N=8 unaffected by source 31", rdata8, 32'h0);
        check("N=2 unaffected by source 31", rdata2, 32'h0);
        wr(2'd3, 32'd31);
        rd(2'd3);
        check("N=32 ack of source 31 clears it", rdata32, 32'h0);
        rd(2'd2);
        check("N=32 PENDING 0 after ack 31", rdata32, 32'h0);
        set_src(32'h3);
        set_src(32'h0);
        rd(2'd2);
        check("N=2 sources 0,1 pending", rdata2, 32'h3);
        check("N=8 sources 0,1 pending", rdata8, 32'h3);
        check("N=32 sources 0,1 pending", rdata32, 32'h3);
        wr(2'd3, 32'd2);
        rd(2'd2);
        check("N=2 ack of source 2 (N or more) changes nothing", rdata2, 32'h3);
        check("N=8 ack of non-pending source 2 changes nothing", rdata8, 32'h3);
        wr(2'd3, 32'd1);
        rd(2'd2);
        check("N=2 ack of source 1", rdata2, 32'h1);
        check("N=8 ack of source 1", rdata8, 32'h1);
        rd(2'd3);
        check("N=2 CLAIM names source 0", rdata2, 32'h8000_0000);
        wr(2'd2, 32'hFFFF_FFFF);
        wr(2'd0, 32'h0);
        wr(2'd1, 32'h0);

        // ---------------- Seeded random traffic against the model ----------------
        phase = "random";
        seed = 32'h1234_5678;
        for (n = 0; n < 4000; n = n + 1) begin
            r1 = $random(seed);
            r2 = $random(seed);
            r3 = $random(seed);
            if (r1[15:8] == 8'd0) begin
                set_rst(1'b0);
                set_rst(1'b1);
            end
            if (r1[6:5] == 2'd0)
                src_v = r3 & $random(seed);
            wd = r2;
            if (r1[7])
                wd = {27'd0, r2[4:0]};
            cyc((r1[1:0] == 2'd0), r1[3:2], wd, src_v);
        end

        phase = "done";
        $display("irq_ctrl testbench: %0d checks passed, %0d failed", pass_cnt, fail_cnt);
        $display("NIRMAAN-SIM %s %0d passed, %0d failed", nonce, pass_cnt, fail_cnt);
        $finish;
    end
endmodule
